"use client";

/**
 * `<Markdown>` — sanitized, GFM-capable markdown renderer for untrusted text.
 *
 * Raw HTML in the source is never rendered. `allowedProtocols` narrows (or widens) the URL
 * schemes kept on `href` and `src`; relative URLs and `#` anchors are always kept.
 *
 * Fenced code renders through `<CodeBlock>`, inline code through `<InlineCode>`, on top of this
 * package's own `a`/`img` defaults (`slideMarkdownComponents`).
 *
 * Component override pattern is forked from `vercel/ai-elements`
 * `<MessageResponse>` (Apache-2.0, see NOTICE).
 */
import { useEffect, useState } from "react";
import type { ComponentPropsWithoutRef, ReactElement, ReactNode } from "react";
import { cn } from "@/lib/cn";
import { CodeBlock } from "@/lib/markdown/code-block";
import { InlineCode } from "@/lib/markdown/inline-code";
import { parseMarkdownToReactSafe } from "@/lib/markdown/parser";
import { slideMarkdownComponents } from "@/lib/markdown/element-defaults";

export interface MarkdownProps
  extends Omit<ComponentPropsWithoutRef<"div">, "children" | "className"> {
  /** Markdown source. Raw HTML in it is never rendered. */
  source: string;
  /**
   * True while tokens are still arriving. Enables the streaming-safe preprocess pass
   * (auto-closes incomplete `**bold`, fences, links, math).
   */
  isStreaming?: boolean;
  /**
   * URL schemes kept on `href` and `src`. Relative URLs and `#` anchors are always kept.
   * Default: the sanitizer's default list.
   */
  allowedProtocols?: readonly string[];
  /** Extra className on the prose wrapper. */
  className?: string;
}

/**
 * Decide whether a hast `code` element is inline (single-backtick) or a
 * fenced block. Heuristic: presence of `language-X` className on `<code>`,
 * or being wrapped in `<pre>` (the runtime sees that as parent). We can't
 * see the parent here, so we use the className signal — fenced code from
 * mdast-util-from-markdown always carries `language-*`.
 */
function isFenced(props: Record<string, unknown>): boolean {
  const cls = props.className as unknown as string | string[] | undefined;
  if (typeof cls === "string") return cls.startsWith("language-");
  if (Array.isArray(cls))
    return cls.some((c) => typeof c === "string" && c.startsWith("language-"));
  return false;
}

function extractLanguage(props: Record<string, unknown>): string | undefined {
  const cls = props.className as unknown as string | string[] | undefined;
  const list = typeof cls === "string" ? [cls] : Array.isArray(cls) ? cls : [];
  for (const c of list) {
    if (typeof c === "string" && c.startsWith("language-")) {
      return c.slice("language-".length);
    }
  }
  return undefined;
}

function extractText(children: ReactNode): string {
  if (typeof children === "string") return children;
  if (Array.isArray(children)) return children.map(extractText).join("");
  if (
    children &&
    typeof children === "object" &&
    "props" in children &&
    (children as { props?: { children?: ReactNode } }).props
  ) {
    return extractText((children as { props: { children?: ReactNode } }).props.children);
  }
  return "";
}

const MARKDOWN_COMPONENTS: Record<string, unknown> = {
  // The package's element defaults FIRST, this surface's overrides after, so a key spelled here
  // wins. `slideMarkdownComponents` supplies `a` and `img`; `code`/`pre` below are the chat's own.
  //
  // ## Why the defaults are spread here and not merged inside `parser.ts`
  //
  // Both were measured before choosing. Merging in the parser resolves the class for every caller,
  // and the class has exactly ONE member: `parseMarkdownToReactSafe` is reachable from no published
  // subpath (106 explicit entries, no wildcard, none targeting `lib/markdown`) and this file is its
  // only caller in the tree — the slide runs its own `primitives/slide/parse.ts`. So the generality
  // buys nothing today, and it costs: a probe of that shape turned `parser.test.ts > renders links`
  // red, because that case asserts the parser's output for a caller passing NO map at all. Changing
  // what the parser does with an absent map is a wider change than this item measured, and it would
  // give the package a third answer to merge-vs-replace next to `slide.tsx`'s deliberate replace.
  //
  // Spreading here changes only the surface the item is about and leaves the parser's contract as
  // it is. If a second caller of the parser ever appears, that is when merging earns its ADR.
  //
  // The map is named for the slide because that is where it was written, not because its content is
  // slide-specific: it sets `loading`/`decoding` on an image and `rel` on an external anchor, which
  // every markdown surface in this package wants. Reused rather than copied — a second definition
  // would be two places to fix the next time a default changes.
  ...slideMarkdownComponents,
  code: (props: Record<string, unknown> & { children?: ReactNode }) => {
    if (isFenced(props)) {
      const language = extractLanguage(props);
      const code = extractText(props.children);
      return <CodeBlock code={code} language={language} />;
    }
    return <InlineCode {...props}>{props.children}</InlineCode>;
  },
  // Strip the default `<pre>` since `<CodeBlock>` ships its own wrapper.
  // Inline `<pre>` still works for raw whitespace-preserving text.
  pre: ({ children }: { children?: ReactNode }) => {
    return <>{children}</>;
  },
};

export function Markdown({
  source,
  isStreaming = false,
  allowedProtocols,
  className,
  ...rest
}: MarkdownProps): ReactElement {
  const [tree, setTree] = useState<ReactElement | null>(null);
  // Key the effect on the schemes' content, not the array identity, so an inline array
  // does not re-parse on every render.
  const protocolsKey = allowedProtocols ? allowedProtocols.join(",") : undefined;

  // biome-ignore lint/correctness/useExhaustiveDependencies: `protocolsKey` stands in for `allowedProtocols`
  useEffect(() => {
    let cancelled = false;
    parseMarkdownToReactSafe(source, {
      isStreaming,
      components: MARKDOWN_COMPONENTS,
      allowedProtocols,
    }).then((next) => {
      if (!cancelled) setTree(next);
    });
    return () => {
      cancelled = true;
    };
  }, [source, isStreaming, protocolsKey]);

  return (
    <div
      data-slot="markdown"
      {...rest}
      className={cn(
        "prose-theo max-w-none text-body-md text-foreground leading-relaxed",
        // First/last child margin reset — fork from vercel/ai-elements
        "[&>*:first-child]:mt-0 [&>*:last-child]:mb-0",
        // Heading sizes use our typescale, not browser defaults
        "[&_h1]:mt-4 [&_h1]:mb-2 [&_h1]:font-semibold [&_h1]:text-title-lg",
        "[&_h2]:mt-3 [&_h2]:mb-2 [&_h2]:font-semibold [&_h2]:text-title-md",
        "[&_h3]:mt-3 [&_h3]:mb-1.5 [&_h3]:font-semibold [&_h3]:text-body-lg",
        "[&_p]:my-2",
        "[&_ul]:my-2 [&_ul]:list-disc [&_ul]:pl-5",
        "[&_ol]:my-2 [&_ol]:list-decimal [&_ol]:pl-5",
        "[&_li]:my-0.5",
        "[&_blockquote]:my-2 [&_blockquote]:border-primary/40 [&_blockquote]:border-l-2 [&_blockquote]:pl-3 [&_blockquote]:text-muted-foreground",
        "[&_a:hover]:text-primary-deep [&_a]:text-primary [&_a]:underline",
        "[&_table]:my-3 [&_table]:w-full [&_table]:border-collapse",
        "[&_th]:border [&_th]:border-border [&_th]:bg-muted/40 [&_th]:px-3 [&_th]:py-1.5 [&_th]:text-left",
        "[&_td]:border [&_td]:border-border [&_td]:px-3 [&_td]:py-1.5",
        "[&_hr]:my-4 [&_hr]:border-border",
        className,
      )}
    >
      {tree}
    </div>
  );
}

/**
 * Markdown → React pipeline for chat messages.
 *
 *   parseMarkdownToReact(md, opts)
 *     ├─ preprocessStreaming(md, isStreaming)  → auto-close incomplete tokens
 *     ├─ parseBody(md)                         → mdast Root (micromark + GFM)
 *     ├─ mdastToHast(mdastTree)                → hast Root (allowDangerousHtml=false)
 *     ├─ sanitizeHast(hastTree)                → hast Root via hast-util-sanitize
 *     └─ hastToReact(hastTree)                 → React tree (jsx-runtime)
 *
 * Every transform lazily imports its peer-dep so the barrel never vendors the
 * markdown stack. Consumers that install the optional peer-deps (already
 * declared by the Slide engine) get rich rendering; consumers that don't get
 * a plain-text fallback via `parseMarkdownToReactSafe`.
 */
import type { Root as HastRoot } from "hast";
import type { Root as MdastRoot } from "mdast";
import { type ReactElement, createElement } from "react";
import { preprocessStreaming } from "@/lib/markdown/streaming-preprocess";

export interface ParseMarkdownOptions {
  /**
   * Override individual element renderers. The `components` map is passed
   * through to `hast-util-to-jsx-runtime` (e.g. `{ code: MyCodeBlock }`).
   */
  components?: Record<string, unknown>;
  /**
   * True while tokens are still arriving from the model. Enables the
   * streaming-safe preprocess pass. Default: `false`.
   */
  isStreaming?: boolean;
  /**
   * URL schemes kept on `href` and `src`. Relative URLs and `#` anchors are always kept.
   * Default: the sanitizer's own default lists.
   */
  allowedProtocols?: readonly string[];
}

export async function parseBody(body: string): Promise<MdastRoot> {
  const [{ fromMarkdown }, { gfmFromMarkdown }, { gfm }] = await Promise.all([
    import("mdast-util-from-markdown"),
    import("mdast-util-gfm"),
    import("micromark-extension-gfm"),
  ]);
  return fromMarkdown(body, {
    extensions: [gfm()],
    mdastExtensions: [gfmFromMarkdown()],
  });
}

export async function mdastToHast(tree: MdastRoot): Promise<HastRoot> {
  const { toHast } = await import("mdast-util-to-hast");
  const hast = toHast(tree, { allowDangerousHtml: false });
  if (!hast || hast.type !== "root") {
    return { type: "root", children: hast ? [hast] : [] } as HastRoot;
  }
  return hast as HastRoot;
}

export async function sanitizeHast(
  tree: HastRoot,
  allowedProtocols?: readonly string[],
): Promise<HastRoot> {
  const { sanitize, defaultSchema } = await import("hast-util-sanitize");
  // Allow class names on `pre`/`code` so syntax-highlight passes survive.
  // `defaultSchema.attributes` uses a wider union than hast-util-sanitize's
  // PropertyDefinition; cast to satisfy the parameter type while preserving
  // the same runtime shape `defaultSchema` already uses.
  const schema = {
    ...defaultSchema,
    attributes: {
      ...(defaultSchema.attributes ?? {}),
      code: [...(defaultSchema.attributes?.code ?? []), ["className", /^language-./]],
      pre: [...(defaultSchema.attributes?.pre ?? []), ["className", /./]],
      span: [...(defaultSchema.attributes?.span ?? []), ["className", /./], ["style"]],
    },
    ...(allowedProtocols
      ? {
          protocols: {
            ...(defaultSchema.protocols ?? {}),
            href: [...allowedProtocols],
            src: [...allowedProtocols],
          },
        }
      : {}),
  } as Parameters<typeof sanitize>[1];
  const safe = sanitize(tree, schema);
  return safe.type === "root"
    ? (safe as HastRoot)
    : ({ type: "root", children: [safe] } as HastRoot);
}

export async function hastToReact(
  tree: HastRoot,
  components?: Record<string, unknown>,
): Promise<ReactElement> {
  const { Fragment, jsx, jsxs } = await import("react/jsx-runtime");
  const { toJsxRuntime } = await import("hast-util-to-jsx-runtime");
  return toJsxRuntime(tree, {
    Fragment,
    jsx,
    jsxs,
    // `components` is `Record<string, unknown>` on our public surface and
    // `Partial<Components>` here. It cannot be typed as the latter: `hast-util-to-jsx-runtime`
    // is an OPTIONAL peer, so naming its types in our published API would make them a hard
    // requirement for every consumer, including the ones who never render markdown. Under
    // React 18's types the two were structurally compatible and this went unnoticed; React
    // 19 tightened the value union and they no longer are. The cast is the adapter at that
    // boundary — the runtime contract is unchanged, and toJsxRuntime validates what it gets.
    components: components as Parameters<typeof toJsxRuntime>[1]["components"],
  }) as ReactElement;
}

/**
 * Public entry point. Returns a Promise<ReactElement> ready to render inline.
 * If any peer-dep is missing at runtime, the function rejects — callers
 * should use `parseMarkdownToReactSafe` for a graceful fallback.
 */
export async function parseMarkdownToReact(
  markdown: string,
  opts: ParseMarkdownOptions = {},
): Promise<ReactElement> {
  const preprocessed = preprocessStreaming(markdown, opts.isStreaming ?? false);
  const mdast = await parseBody(preprocessed);
  const hast = await mdastToHast(mdast);
  const safe = await sanitizeHast(hast, opts.allowedProtocols);
  return hastToReact(safe, opts.components);
}

/**
 * Same as `parseMarkdownToReact` but returns a plain-text `<span>` fallback
 * if any peer-dep is missing (instead of rejecting). Used by `<ChatMessage>`
 * to keep the surface rendering when consumers opted out of the markdown
 * stack.
 */
export async function parseMarkdownToReactSafe(
  markdown: string,
  opts: ParseMarkdownOptions = {},
): Promise<ReactElement> {
  try {
    return await parseMarkdownToReact(markdown, opts);
  } catch {
    return createElement("span", { className: "whitespace-pre-wrap" }, markdown);
  }
}

/**
 * Streaming-safe markdown preprocessor.
 *
 * When markdown arrives token-by-token from an LLM, the tail of the buffer
 * is almost always mid-token: `**bold` (unclosed), `[link` (no `]`), an
 * unterminated ` ```fence`, an unfinished `$math$`. A vanilla markdown
 * parser treats those as literal text — the user sees `**bold` instead of
 * **bold** for the few hundred ms until the matching token arrives. This
 * "flash" is the single biggest UX defect of naïve streaming markdown
 * (cf. Streamdown's design note).
 *
 * The trick — adopted from Streamdown (MIT, vercel) and re-implemented
 * here — is to NEVER mutate the original buffer (the model's authoritative
 * stream), but to feed a TRANSIENTLY auto-closed copy to the parser. When
 * the next token actually closes the syntax, the temporary close was a
 * no-op and the real one takes over.
 *
 * Scope:
 *   - bold/italic markers: `**`, `__`, `*`, `_`
 *   - inline code: single backtick `` ` ``
 *   - fenced code: triple-backtick (with optional language)
 *   - inline math: `$` … `$`
 *   - block math: `$$` … `$$`
 *   - links: `[text](url)` — close the `)` if missing
 *
 * Out of scope (yet):
 *   - reference-style links `[text][ref]` — rare in LLM output
 *   - HTML tags — Tailwind v4 already sanitizes downstream
 *   - tables — partial tables render OK as plain text mid-stream
 */

/**
 * Auto-close incomplete markdown tokens in the tail of a streaming buffer.
 * Returns a copy that's safe to pass to the parser; the original buffer
 * stays untouched.
 *
 * `isStreaming = false` short-circuits (returns input unchanged) — the
 * close-tokens are only synthesized while content is still arriving.
 */
export function preprocessStreaming(markdown: string, isStreaming = true): string {
  if (!isStreaming) return markdown;

  let buf = markdown;

  /* ─── Fenced code blocks (highest priority — they swallow everything) */
  // If there's an odd number of ``` runs, the last fence is unclosed.
  const fenceCount = countTripleBackticks(buf);
  if (fenceCount % 2 === 1) {
    // Add a newline + closing fence so the parser sees a complete block.
    buf = `${buf.endsWith("\n") ? buf : `${buf}\n`}\`\`\``;
    // Once inside an unclosed fence the rest of the rules don't apply —
    // everything is code text.
    return buf;
  }

  /* ─── Block math `$$ … $$` (also greedy) */
  const blockMathCount = countOccurrences(buf, "$$");
  if (blockMathCount % 2 === 1) {
    buf = `${buf}$$`;
    return buf;
  }

  /* ─── Inline code, single backticks */
  const inlineBackticks = countSingleBackticks(buf);
  if (inlineBackticks % 2 === 1) {
    buf = `${buf}\``;
  }

  /* ─── Inline math `$ … $` (avoid double-counting `$$`) */
  const inlineDollars = countSingleDollars(buf);
  if (inlineDollars % 2 === 1) {
    buf = `${buf}$`;
  }

  /* ─── Emphasis pairs */
  // Order matters: close longer markers before shorter (`**` before `*`).
  for (const marker of ["**", "__", "*", "_"]) {
    if (countMarker(buf, marker) % 2 === 1) {
      buf = `${buf}${marker}`;
    }
  }

  /* ─── Links: `[text](url)` — close the URL paren if missing.
   * Cheap heuristic: find the last `[` after the last `]`, and the last
   * `(` after that with no matching `)`.
   */
  buf = closeUnclosedLink(buf);

  return buf;
}

/* ─── Counting helpers (avoid regex global-state pitfalls) ───────────── */

function countTripleBackticks(s: string): number {
  let count = 0;
  let i = 0;
  while (i < s.length) {
    if (s[i] === "`" && s[i + 1] === "`" && s[i + 2] === "`") {
      count++;
      i += 3;
    } else {
      i++;
    }
  }
  return count;
}

function countSingleBackticks(s: string): number {
  // Count ` characters that are NOT part of a ``` run.
  let count = 0;
  let i = 0;
  while (i < s.length) {
    if (s[i] === "`") {
      if (s[i + 1] === "`" && s[i + 2] === "`") {
        i += 3; // skip whole triple
        continue;
      }
      count++;
    }
    i++;
  }
  return count;
}

function countOccurrences(s: string, needle: string): number {
  if (needle.length === 0) return 0;
  let count = 0;
  let i = s.indexOf(needle);
  while (i !== -1) {
    count++;
    i = s.indexOf(needle, i + needle.length);
  }
  return count;
}

function countSingleDollars(s: string): number {
  // Single `$` that is NOT part of `$$`.
  let count = 0;
  let i = 0;
  while (i < s.length) {
    if (s[i] === "$") {
      if (s[i + 1] === "$") {
        i += 2; // skip whole pair
        continue;
      }
      // also skip escaped \$
      if (i > 0 && s[i - 1] === "\\") {
        i++;
        continue;
      }
      count++;
    }
    i++;
  }
  return count;
}

function countMarker(s: string, marker: string): number {
  if (marker.length === 0) return 0;
  // For single-char markers (`*`, `_`), don't count double sequences as 2 —
  // they ARE the double marker. For double-char markers, count occurrences
  // and the single-marker pass below handles leftovers.
  if (marker.length === 1) {
    let count = 0;
    let i = 0;
    while (i < s.length) {
      if (s[i] === marker) {
        if (s[i + 1] === marker) {
          // Part of double marker — skip both.
          i += 2;
          continue;
        }
        if (i > 0 && s[i - 1] === "\\") {
          i++;
          continue;
        }
        count++;
      }
      i++;
    }
    return count;
  }
  // Multi-char marker (`**`, `__`).
  let count = 0;
  let i = 0;
  while (i <= s.length - marker.length) {
    if (s.substring(i, i + marker.length) === marker) {
      count++;
      i += marker.length;
    } else {
      i++;
    }
  }
  return count;
}

function closeUnclosedLink(s: string): string {
  // Look for the trailing structure `[…](…` with no closing `)`.
  const lastOpenParen = s.lastIndexOf("(");
  const lastCloseParen = s.lastIndexOf(")");
  if (lastOpenParen === -1 || lastOpenParen <= lastCloseParen) return s;

  // The `(` must be immediately preceded by `]` to be a link.
  if (s[lastOpenParen - 1] !== "]") return s;

  // Confirm there's a `[` before that `]`.
  const closingBracket = lastOpenParen - 1;
  const openingBracket = s.lastIndexOf("[", closingBracket - 1);
  if (openingBracket === -1) return s;

  // Close it.
  return `${s})`;
}

"use client";

/**
 * `<CodeBlock>` — fenced code block with syntax highlight + copy button.
 *
 * Lazy-loads `shiki` (peer-dep optional). If shiki is not installed, falls
 * back to a plain `<pre><code>` with the language label still visible. The
 * copy button works in both modes (clipboard API only).
 *
 * Inspired by `shadcn.io`'s AI code-block pattern:
 *   - language label top-left
 *   - copy button top-right, icon swap (Copy → Check) for ~2s after success
 *   - keyboard accessible (button is a real <button>)
 *   - SSR-safe: highlighted markup is sync-rendered when ready; before
 *     hydration, plain text shows (matches Slide's shiki plugin behavior).
 *
 * Used by `parseMarkdownToReact` via the `components.code` override.
 */
import { CheckIcon, CopyIcon } from "lucide-react";
import { useEffect, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

export interface CodeBlockProps {
  /** The raw source code. Newlines preserved verbatim. */
  code: string;
  /** Language hint (`typescript`, `python`, `bash`, …). Falls through if unknown. */
  language?: string;
  /** Dual-theme map — Shiki theme names. */
  themes?: { light: string; dark: string };
  /** Extra className for the outer wrapper. */
  className?: string;
}

const DEFAULT_THEMES = { light: "github-light", dark: "github-dark" };

let cachedHighlighter: unknown = null;
let highlighterFailed = false;

async function getHighlighter(themes: { light: string; dark: string }): Promise<unknown> {
  if (cachedHighlighter) return cachedHighlighter;
  if (highlighterFailed) return null;
  try {
    const shiki = await import("shiki");
    cachedHighlighter = await shiki.createHighlighter({
      themes: [themes.light, themes.dark],
      langs: [
        "ts",
        "tsx",
        "js",
        "jsx",
        "python",
        "go",
        "rust",
        "java",
        "json",
        "yaml",
        "bash",
        "shell",
        "html",
        "css",
        "sql",
        "markdown",
      ],
    });
    return cachedHighlighter;
  } catch {
    highlighterFailed = true;
    return null;
  }
}

export function CodeBlock({ code, language, themes, className }: CodeBlockProps): JSX.Element {
  const [html, setHtml] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const effectiveThemes = themes ?? DEFAULT_THEMES;

  useEffect(() => {
    let cancelled = false;
    if (!language) return;
    getHighlighter(effectiveThemes)
      .then((hl) => {
        if (cancelled || !hl) return;
        try {
          // biome-ignore lint/suspicious/noExplicitAny: shiki Highlighter is untyped here
          const out = (hl as any).codeToHtml(code, {
            lang: language,
            themes: { light: effectiveThemes.light, dark: effectiveThemes.dark },
            defaultColor: "light",
          });
          setHtml(out);
        } catch {
          // unknown language or grammar load error — pass through plain
        }
      })
      .catch(() => {
        // peer-dep missing — silent; plain <pre><code> below renders
      });
    return () => {
      cancelled = true;
    };
  }, [code, language, effectiveThemes.light, effectiveThemes.dark, effectiveThemes]);

  const handleCopy = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard denied — silent */
    }
  };

  return (
    <div
      className={cn(
        "group relative my-4 overflow-hidden rounded-lg border border-border bg-muted/30",
        className,
      )}
      data-theo-code-block=""
    >
      <div className="flex items-center justify-between border-border border-b bg-muted/50 px-3 py-1.5">
        <span className="font-mono text-label-caps text-muted-foreground uppercase tracking-wider">
          {language || "text"}
        </span>
        <button
          type="button"
          onClick={handleCopy}
          className={cn(
            "inline-flex h-7 items-center gap-1.5 rounded-md px-2 text-label",
            "text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground",
            "focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring",
          )}
          aria-label={copied ? "Copied" : "Copy code"}
        >
          {copied ? (
            <>
              <CheckIcon className="size-3.5" aria-hidden="true" />
              <span>Copied</span>
            </>
          ) : (
            <>
              <CopyIcon className="size-3.5" aria-hidden="true" />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>
      {html ? (
        <div
          className="[&_pre]:!bg-transparent [&_pre]:!m-0 [&_pre]:!p-0 overflow-x-auto p-3 text-code-sm"
          // biome-ignore lint/security/noDangerouslySetInnerHtml: Shiki output is sanitized HTML it produced itself; no user input flows through
          dangerouslySetInnerHTML={{ __html: html }}
        />
      ) : (
        <pre className="overflow-x-auto p-3 text-code-sm">
          <code className={language ? `language-${language}` : undefined}>{code}</code>
        </pre>
      )}
    </div>
  );
}

/**
 * `<InlineCode>` — styled inline `<code>` for markdown rendering.
 *
 * Differentiates inline code from fenced code-blocks (which use `<CodeBlock>`)
 * via subtle surface treatment. Per Violet Forge: muted background, mono
 * font, slight horizontal padding.
 */
import type { HTMLAttributes } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

export type InlineCodeProps = HTMLAttributes<HTMLElement>;

export function InlineCode({ className, children, ...props }: InlineCodeProps): JSX.Element {
  return (
    <code
      className={cn(
        "rounded bg-muted px-1.5 py-0.5 font-mono text-code-sm text-foreground",
        className,
      )}
      {...props}
    >
      {children}
    </code>
  );
}

"use client";

/**
 * KaTeX math rendering — inline and block.
 *
 * `<MathInline>` for `$x + y$`, `<MathBlock>` for `$$\sum_i x_i$$`. Both
 * lazy-load `katex` (peer-dep optional). When `katex` is not installed the
 * component renders a plain `<code>` fallback so the chat surface stays
 * usable.
 *
 * Markdown integration: enable in `parseMarkdownToReact` via the
 * `components` map (`{ "math-inline": MathInline, "math-block": MathBlock }`)
 * once a math mdast extension is wired in (`mdast-util-math`, peer-dep).
 */
import { useEffect, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

interface KatexLib {
  renderToString: (
    tex: string,
    opts?: { displayMode?: boolean; throwOnError?: boolean; output?: string },
  ) => string;
}

let katexCache: KatexLib | null = null;
let katexFailed = false;

async function loadKatex(): Promise<KatexLib | null> {
  if (katexCache) return katexCache;
  if (katexFailed) return null;
  try {
    const mod = (await import("katex")) as unknown as { default?: KatexLib } & KatexLib;
    // `katex` ships UMD-default; both shapes exist depending on the bundler.
    const lib = mod.default ?? mod;
    katexCache = lib;
    return katexCache;
  } catch {
    katexFailed = true;
    return null;
  }
}

interface MathProps {
  /** The TeX source string (without `$` or `$$` wrappers). */
  tex: string;
  /** Inline (true) vs display (false). */
  inline: boolean;
  className?: string;
}

function MathImpl({ tex, inline, className }: MathProps): JSX.Element {
  const [html, setHtml] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    loadKatex().then((katex) => {
      if (cancelled || !katex) return;
      try {
        const out = katex.renderToString(tex, {
          displayMode: !inline,
          throwOnError: false,
          output: "html",
        });
        setHtml(out);
      } catch {
        /* invalid TeX — leave plain fallback */
      }
    });
    return () => {
      cancelled = true;
    };
  }, [tex, inline]);

  if (!html) {
    const Tag = inline ? "code" : "pre";
    return (
      <Tag
        className={cn(
          inline
            ? "rounded bg-muted px-1.5 py-0.5 font-mono text-code-sm"
            : "my-3 overflow-x-auto rounded-lg border border-border bg-muted/30 p-3 font-mono text-code-sm",
          className,
        )}
      >
        {tex}
      </Tag>
    );
  }

  const Tag = inline ? "span" : "div";
  return (
    <Tag
      className={cn(inline ? "katex-inline" : "katex-block my-3 overflow-x-auto", className)}
      // biome-ignore lint/security/noDangerouslySetInnerHtml: KaTeX renderToString output is sanitized HTML it produced itself; only `tex` (already-sanitized markdown content) flows in
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

export type MathInlineProps = Omit<MathProps, "inline">;
export type MathBlockProps = Omit<MathProps, "inline">;

export function MathInline(props: MathInlineProps): JSX.Element {
  return <MathImpl {...props} inline={true} />;
}

export function MathBlock(props: MathBlockProps): JSX.Element {
  return <MathImpl {...props} inline={false} />;
}

"use client";

/**
 * `<MermaidDiagram>` — Mermaid diagram renderer.
 *
 * Renders a Mermaid source code block as an inline SVG. Lazy-loads
 * `mermaid` (peer-dep optional, ~200 KB) on mount; falls back to a
 * styled `<pre>` showing the raw source when the peer-dep is missing
 * OR when parsing the diagram fails (invalid syntax).
 *
 * Security note: Mermaid v11+ initialize with `securityLevel: "strict"`
 * by default, which sanitizes HTML inside diagram labels and disables
 * `click` interactions. We re-assert that here.
 *
 * In a chat context an unverified LLM response could include a malformed
 * or hostile diagram — auto-rendering is acceptable under strict mode
 * because the produced SVG goes through Mermaid's own sanitizer first.
 */
import { useEffect, useRef, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

interface MermaidLib {
  initialize: (opts: { startOnLoad?: boolean; securityLevel?: string; theme?: string }) => void;
  render: (id: string, src: string) => Promise<{ svg: string }>;
}

let mermaidCache: MermaidLib | null = null;
let mermaidFailed = false;

async function loadMermaid(): Promise<MermaidLib | null> {
  if (mermaidCache) return mermaidCache;
  if (mermaidFailed) return null;
  try {
    const mod = (await import("mermaid")) as unknown as { default?: MermaidLib } & MermaidLib;
    const lib = mod.default ?? mod;
    if (!lib || typeof lib.initialize !== "function") {
      mermaidFailed = true;
      return null;
    }
    lib.initialize({
      startOnLoad: false,
      securityLevel: "strict",
      theme: "default",
    });
    mermaidCache = lib;
    return mermaidCache;
  } catch {
    mermaidFailed = true;
    return null;
  }
}

let renderCounter = 0;

export interface MermaidDiagramProps {
  /** The Mermaid source code (e.g. `flowchart TD\nA-->B`). */
  source: string;
  className?: string;
}

export function MermaidDiagram({ source, className }: MermaidDiagramProps): JSX.Element {
  const [svg, setSvg] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const idRef = useRef(`theo-mermaid-${++renderCounter}`);

  useEffect(() => {
    let cancelled = false;
    loadMermaid().then(async (mermaid) => {
      if (cancelled || !mermaid) {
        if (!cancelled) setFailed(true);
        return;
      }
      try {
        const { svg: out } = await mermaid.render(idRef.current, source);
        if (!cancelled) setSvg(out);
      } catch {
        if (!cancelled) setFailed(true);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [source]);

  if (svg) {
    return (
      <div
        className={cn("my-4 flex justify-center overflow-x-auto", className)}
        data-theo-mermaid=""
        // biome-ignore lint/security/noDangerouslySetInnerHtml: Mermaid render() output is sanitized SVG it produced itself under securityLevel="strict"; only `source` (already-sanitized markdown content) flows in
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    );
  }

  return (
    <pre
      className={cn(
        "my-4 overflow-x-auto rounded-lg border border-border bg-muted/30 p-3 text-code-sm",
        failed && "border-warning/40",
        className,
      )}
      data-theo-mermaid-fallback={failed ? "true" : "loading"}
    >
      <code className="language-mermaid">{source}</code>
    </pre>
  );
}

import type { ComponentProps, JSX } from "react";

import { safeHref } from "@/lib/safe-href";

/**
 * The defaults a slide's markdown gets when the consumer passes no `components` map.
 *
 * usetheokit/theokit-ui#154: `<Slide components={...}>` has been public API since the primitive
 * shipped and `parse.ts` passes whatever it gets straight to `toJsxRuntime` — but nothing supplied a
 * default, so `![]()` and `[]()` rendered as bare `<img>` and `<a>` with none of the defaults this
 * package applies wherever it renders one itself.
 *
 * ## What this is NOT
 *
 * Not a security fix. The issue framed the link half that way — a `target="_blank"` link without
 * `rel="noopener"` hands the opened page a live `window.opener` — and the premise does not hold:
 * the sanitize schema strips `target`, measured on `hast-util-sanitize`'s own output. A markdown
 * link cannot open a new browsing context at all, so the opener is never handed to anything.
 *
 * `rel` is here as DEFENCE IN DEPTH, and the distinction matters for whoever reads this next:
 * `getSlideSanitizeSchema` unions plugin-declared attributes onto the baseline, so a plugin
 * declaring `a: ["target"]` reopens the door. With this default the protection travels with the
 * anchor instead of depending on nobody ever widening the schema.
 *
 * ## Why a plain element and not the package's own components
 *
 * There is no `Image` component in this package — measured, not assumed. Mapping markdown onto a
 * component that does not exist is the kind of plan that reads well and cannot ship. What markdown
 * was missing is the ATTRIBUTES, and those are what this supplies.
 */

/** A link's destination is another origin, so an opener reference would cross a boundary. */
function isExternal(href: string | undefined): boolean {
  if (href === undefined || href === "") return false;
  // Fragment and relative links stay in this document. A default that fired on `#section` would be
  // noise, and a noisy default is one consumers replace wholesale rather than extend.
  if (href.startsWith("#") || href.startsWith("/") || href.startsWith("./")) return false;
  return /^[a-z][a-z0-9+.-]*:/i.test(href);
}

/**
 * `Record<string, unknown>` on the surface, for the reason `parse.ts` records: the JSX-runtime types
 * come from an OPTIONAL peer, and naming them here would make that peer a hard requirement for every
 * consumer — including the ones who never render markdown.
 */
export const slideMarkdownComponents: Record<
  string,
  ((props: Record<string, unknown>) => JSX.Element) | undefined
> = {
  a(props) {
    const { href, children, ...rest } = props as ComponentProps<"a"> & {
      children?: React.ReactNode;
    };
    // `safeHref` rather than a second protocol check: it already refuses `javascript:` and `data:`
    // and is what `loadThemeFonts` trusts for the same question. One answer, one place.
    const safe = typeof href === "string" ? safeHref(href) : undefined;
    const external = isExternal(safe);
    return (
      <a {...rest} href={safe} rel={external ? "noopener noreferrer" : undefined}>
        {children}
      </a>
    );
  },

  img(props) {
    const { src, alt, ...rest } = props as ComponentProps<"img">;
    const safe = typeof src === "string" ? safeHref(src) : undefined;
    return (
      <img
        {...rest}
        src={safe}
        // `alt=""` and no alt are different claims to a screen reader: the first says "skip me", the
        // second makes it read the URL aloud. `![](x.png)` is an author saying there is nothing to
        // announce, so the empty string is the honest translation of it.
        alt={typeof alt === "string" ? alt : ""}
        loading="lazy"
        decoding="async"
      />
    );
  },
};
